mapper.select:
SELECT * FROM statistics_info
WHERE statistics_date = #{statisticsDate}
AND user_id = #{userId}
AND data_type = #{dataType}

        select ifnull(sum(s.statistics_count),0)statistics_count, s.data_type, s.statistics_date
        from statistics_info s
        
            
                and s.statistics_date = #{query.statisticsDate}
            
            
                and s.user_id = #{query.userId}
            
            
                and s.data_type = #{query.dataType}
            
            
                and s.statistics_date >= #{query.statisticsDateStart}
            
            
                and s.statistics_date <= #{query.statisticsDateEnd}
            
        
        group by s.data_type, s.statistics_date
        
            ORDER BY ${query.orderBy}

mapper.update:
UPDATE statistics_info
SET statistics_count = #{statisticsCount}
WHERE statistics_date = #{statisticsDate}
AND user_id = #{userId}
AND data_type = #{dataType}

mapper.delete:
DELETE FROM statistics_info
WHERE statistics_date = #{statisticsDate}
AND user_id = #{userId}
AND data_type = #{dataType}
